CREATE TABLE IF NOT EXISTS homepage_sections (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,section_key VARCHAR(100) NOT NULL UNIQUE,is_active TINYINT(1) NOT NULL DEFAULT 1,sort_order INT NOT NULL DEFAULT 0,title VARCHAR(255) NULL,description MEDIUMTEXT NULL,payload JSON NULL,created_at TIMESTAMP NULL,updated_at TIMESTAMP NULL,INDEX(is_active),INDEX(sort_order)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS store (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,store_name VARCHAR(180) NOT NULL,address MEDIUMTEXT NULL,phone VARCHAR(50) NULL,whatsapp VARCHAR(50) NULL,email VARCHAR(190) NULL,working_hours MEDIUMTEXT NULL,maps_url VARCHAR(1000) NULL,maps_embed MEDIUMTEXT NULL,latitude DECIMAL(10,7) NULL,longitude DECIMAL(10,7) NULL,hero_media_id BIGINT UNSIGNED NULL,exterior_media_id BIGINT UNSIGNED NULL,created_at TIMESTAMP NULL,updated_at TIMESTAMP NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS menus (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,location VARCHAR(80) NOT NULL UNIQUE,created_at TIMESTAMP NULL,updated_at TIMESTAMP NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS menu_items (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,menu_id BIGINT UNSIGNED NOT NULL,parent_id BIGINT UNSIGNED NULL,label VARCHAR(160) NOT NULL,url VARCHAR(1000) NOT NULL,target VARCHAR(20) NOT NULL DEFAULT '_self',sort_order INT NOT NULL DEFAULT 0,is_active TINYINT(1) NOT NULL DEFAULT 1,created_at TIMESTAMP NULL,updated_at TIMESTAMP NULL,FOREIGN KEY(menu_id) REFERENCES menus(id) ON DELETE CASCADE,FOREIGN KEY(parent_id) REFERENCES menu_items(id) ON DELETE CASCADE,INDEX(menu_id,sort_order)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS seo (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,entity_type VARCHAR(100) NOT NULL,entity_id BIGINT UNSIGNED NOT NULL,seo_title VARCHAR(255) NULL,meta_description VARCHAR(500) NULL,canonical_url VARCHAR(1000) NULL,og_title VARCHAR(255) NULL,og_description VARCHAR(500) NULL,og_media_id BIGINT UNSIGNED NULL,robots VARCHAR(100) NULL,created_at TIMESTAMP NULL,updated_at TIMESTAMP NULL,UNIQUE KEY unique_seo_entity(entity_type,entity_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS login_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NULL,event VARCHAR(40) NOT NULL,ip_address VARCHAR(45) NULL,user_agent VARCHAR(500) NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL,INDEX(event),INDEX(created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS failed_logins (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,identity_value VARCHAR(190) NOT NULL,ip_address VARCHAR(45) NULL,user_agent VARCHAR(500) NULL,attempted_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX(identity_value),INDEX(ip_address),INDEX(attempted_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS backups (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,filename VARCHAR(255) NOT NULL UNIQUE,path VARCHAR(500) NOT NULL UNIQUE,file_size BIGINT UNSIGNED NULL,created_by BIGINT UNSIGNED NULL,status VARCHAR(30) NOT NULL DEFAULT 'completed',created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
